uirements."]', '[{"label": "Laser type", "value": "Pulsed Fiber Laser"}, {"label": "Working Area", "value": "100x100, 175x175, 250x250, 300x300 Mm & Customized"}, {"label": "Laser Power", "value": "20, 30, 50, 60, 100 W"}, {"label": "Operating System", "value": "Win 7/8/10/11"}, {"label": "Supported File", "value": "PLT, DXF, BMP, JPG, GLF, PNG."}, {"label": "Working Volt", "value": "Single Phase 220-230v/50hz (Earthing Req)"}, {"label": "Wavelength:", "value": "1064 nm"}, {"label": "Power Adjusting Range", "value": "1-100%"}, {"label": "Max. Linear Speed", "value": "Max 12000 Mm/S"}, {"label": "Min. Character Height", "value": "0.1 MM"}]', '["flm1.png", "flm2.png", "flm3.png", "flm4.png", "flm5.png", "flm6.png", "flm7.png", "flm8.png", "flm9.png", "flm10.png", "flm11.png", "flm12.png"]', 'Fiber Laser Marking Machine', '2026-08-05 05:06:28.983098+00', 'Fiber Laser Marking Machine, Buy Fiber Laser Marking Machines, Fiber Laser Marking Machine Price', 'Fiber Laser Marking Machine | Manufacturer in India', 'Fiber laser marking machines for metal, plastic and jewellery. 20W-100W models with customizable marking areas for industrial applications.', '["Fiber Laser Marking Machine Manufacturer", "Fiber Laser Marking Machine in India", "Fiber Laser Marking Machine Price", "Fiber Laser Marking Machine Supplier", "Industrial Fiber Laser Marking Machine", "Fiber Laser Marking Machine for Metal", "20W Fiber Laser Marking Machine", "30W Fiber Laser Marking Machine", "50W Fiber Laser Marking Machine", "100W Fiber Laser Marking Machine"]'), (2, 'fiber-laser-cutting-machine', 'Fiber Laser Cutting Machine', 'Fiber Laser Cutting Machine', 'Paratech Industries', 'fiberlasercuttingmachine.jpeg', '["fiberlasercuttingmachine.jpeg"]', 'Which Materials You Can Mark !!', 'SS, MS,Aluminium, Cast Iron, Plastic, Gold, Silver, Platinum, Coated Glass, Bronze, Titanium, Copper, Brass, Carbide, Non Transparent Acrylic & More...', '["<a href=\\"https://paratechindustries.com/\\">Paratech Industries</a> manufactures and exports high-precision Fiber Laser Cutting Machines from Surat, Gujarat, India, engineered for industrial sheet metal cutting across a 500W to 5KW power range using IPG, Raycus, or Max fiber laser sources.", "Each fiber laser cutting machine is built with a Swiss Raytools laser head, Cypcut control system, and dual-drive rack-and-pinion transmission on Taiwan Hiwin guide rails for stable, repeatable cuts. With a working area of 1500x3000mm and X/Y axis repeat positioning precision of ±0.02mm, our CNC fiber laser cutting machines handle SS, MS, aluminium, brass, copper, titanium, and carbide with clean edges and minimal material waste.", "Powered by a three-phase 380V supply and fitted with auto lubrication, wireless handle control, and Japan Yaskawa servo motors, this metal laser cutting machine is built for continuous industrial production runs. Paratech Industries backs every fiber laser cutting machine with catalogue specs, installation support, and after-sales service across India."]', '[{"label": "Fiber Laser Source", "value": "IPG/Raycus/Max-500W/1KW/1.5KW/2KW/3KW/5KW"}, {"label": "Laser Head", "value": "Swiss Raytools Laser Head"}, {"label": "Transmission System", "value": "Dual Drive Precise and Pinion"}, {"label": "Guide Rail", "value": "Taiwan Hiwin"}, {"label": "Rack & Pinion", "value": "Taiwan Yyc"}, {"label": "Speed Reducer", "value": "Japan Shimpo"}, {"label": "Servo Motor", "value": "Japan Yaskawa"}, {"label": "Water Chiller", "value": "Hanli"}, {"label": "Control System", "value": "Cypcut"}, {"label": "Proportional Valve", "value": "Japan Smc"}, {"label": "Auxiliary Parts", "value": "Exhaust Fan"}, {"label": "Electronics", "value": "France Schneider"}, {"label": "Computer", "value": "Yes"}, {"label": "Auto Lubrication", "value": "Yes"}, {"label": "Wireless Handle Control", "value": "Yes"}, {"label": "Working Area (L*W)", "value": "1500 x 3000"}, {"label": "X/Y Axis Repeated Position Precision", "value": "-0.02mm"}, {"label": "Machine Gross Weight", "value": "3.0T"}, {"label": "Voltage", "value": "Three-Phase 380V 50/60Hz"}]', '["fc1.png", "fc2.png", "fc3.png"]', 'Fiber Laser Cutting Machine', '2026-08-05 05:06:28.983098+00', 'Fiber Laser Cutting Machine, Fiber Laser Cutting Machine Price', 'Fiber Laser Cutting Machine Manufacturer in Surat, Gujarat', 'High-precision CNC Fiber Laser Cutting Machines from 500W to 5KW for sheet metal cutting. Swiss Raytools head & Cypcut system. Manufacturer in Surat.', '["Fiber Laser Cutting Machine", "Fiber Laser Cutting Machine Manufacturer", "CNC Fiber Laser Cutting Machine", "Sheet Metal Laser Cutting Machine", "Raytools Laser Head Cutting Machine", "High Precision Fiber Laser Cutter", "Paratech Industries Fiber Laser Cutting Machine"]'), (3, 'handheld-fiber-laser-welding-machine', 'Handheld Fiber Laser Welding Machine', 'Handheld Laser Welding Machine', 'Paratech Industries', 'handheldfiberlaserweldingmachine.jpeg', '["handheldfiberlaserweldingmachine.jpeg"]', 'Which Materials You Can Mark !!', 'STAINLESS STEEL, MILD STEEL, ALUMINUM', '["<a href=\\"https://paratechindustries.com/\\">Paratech Industries</a> manufactures Handheld Fiber Laser Welding Machines in Surat, Gujarat, India, built for industrial welding of stainless steel, mild steel, and aluminium. Available in 1000W, 1500W, and 2000W laser source options, each handheld metal fiber laser welding machine delivers a stable 1070nm (±10nm) output with a 0-150mm cleaning width for combined welding and cleaning applications.", "Whether you need a 1.5kW handheld fiber laser welding machine for fabrication shops or a 2000W fiber laser welding machine for heavy-duty metal joining, Paratech Industries backs every unit with catalogue documentation and after-sales support across India."]', '[{"label": "Model", "value": "Operating temperature (°c)"}, {"label": "Laser source", "value": "1000w/1500w/2000w"}, {"label": "Rated output", "value": "1000w/1500w/2000w"}, {"label": "Max output power", "value": "1070 (